/// <summary>
/// Determines whether the <c>LedgerJournalTable</c> transaction can be posted.
/// </summary>
/// <param name = "_ledgerJournalTable">
/// The <c>LedgerJournalTable</c> record.
/// </param>
/// <returns>
/// Returns true if the transaction can be posted; otherwise, false.
/// </returns>
protected final boolean canLedgerJournalTableBePosted(LedgerJournalTable _ledgerJournalTable)
{
    boolean ret = next canLedgerJournalTableBePosted(_ledgerJournalTable);
    if (ret)
    {
        ret = !(_ledgerJournalTable.AVACopiedWithDifLayer || _ledgerJournalTable.AVAPostedWithDifLayer);
    }
    return ret;
}

/// <summary>
/// Sets the post and delete button state.
/// </summary>
public void datasourceMarkChangedPost()
{
    next datasourceMarkChangedPost();

    if (this.journalTable_DS().table() == tableNum(LedgerJournalTable))
    {
        LedgerJournalTable ledgerJournalTable_bec = this.journalTable_DS().cursor();
        if ((ledgerJournalTable_bec.AVACopiedWithDifLayer || ledgerJournalTable_bec.AVAPostedWithDifLayer))
        {
            this.journalTable_DS().allowDelete(false);
        }
    }
}
